pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(uint256 balanceBefore, uint256 msgValue, uint256 unlockTime) public {
        // Restrict msgValue to a wide range that still allows overflow scenarios.
        // We allow msgValue up to type(uint256).max to enable the buggy overflow path.
        vm.assume(msgValue > 0);

        // We need an initial balance that, when added to msgValue, could overflow.
        // The correct contract checks for overflow and reverts, while the buggy one wraps.
        // To set up a specific account state, we use a fresh address and set its balance via Put.
        address actor = address(uint160(uint256(keccak256(abi.encodePacked("actor", balanceBefore, msgValue, unlockTime)))));

        // Ensure we don't collide with pre-funded addresses
        vm.assume(actor != address(this) && actor != address(0) && actor.code.length == 0);

        // Set up the initial balance on the actor's account in C to balanceBefore.
        // Since Put requires msg.value, we send the exact amount as Ether to establish the balance.
        // We restrict balanceBefore to avoid the initial Put from overflowing (it must succeed in the ref impl).
        vm.assume(balanceBefore <= type(uint256).max - balanceBefore); // silly tautology, use concrete bound
        vm.assume(balanceBefore < type(uint256).max);

        // First, establish the initial balance with a safe Put that won't overflow the ref impl.
        // We deal ether and call Put.
        vm.deal(actor, balanceBefore);
        vm.prank(actor);
        c.Put{value: balanceBefore}(0);

        // Now, attempt a second Put with msg.value = msgValue.
        // This call may succeed or revert depending on the implementation.
        // We capture the revert status.
        bool success;
        uint256 balanceBeforeSecond = c.Acc(actor).balance;

        vm.deal(actor, msgValue);
        vm.prank(actor);
        try c.Put{value: msgValue}(unlockTime) {
            success = true;
        } catch {
            success = false;
        }

        uint256 balanceAfterSecond = c.Acc(actor).balance;

        if (success) {
            // If the call succeeded, in the reference implementation balance must have increased.
            // Because the overflow check ensures balanceBeforeSecond + msgValue >= balanceBeforeSecond.
            // In the buggy implementation, if overflow occurs, balanceAfterSecond < balanceBeforeSecond.
            assertTrue(balanceAfterSecond > balanceBeforeSecond);
        }
        // If it reverted, both implementations are consistent (the ref reverts on overflow, bug may not,
        // but a revert is acceptable for this property).
    }
}

