pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // Keep amount within a reasonable range but allow numbers that could contribute to overflow
        // after multiple calls. We restrict to avoid exhausting fuzz resources, but keep it wide.
        bound(amount, 0, type(uint128).max);
        vm.assume(amount > 0);

        // Set up a fresh sender with plenty of ether
        address sender = address(0x1000);
        vm.deal(sender, type(uint256).max);

        // Record the contract balance before Put
        uint256 balanceBefore = address(c).balance;

        // Call Put as the sender, catching revert explicitly
        bool ok;
        vm.prank(sender);
        try c.Put{value: amount}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, the total recorded balance across all accounts
        // must equal the contract's ether balance.
        // We only check when Put succeeds, because the invariant is trivially true
        // before any transactions.
        if (ok) {
            // Put only affects msg.sender, so we sum balances from Acc getter
            // We iterate *all possible addresses* is impossible, but we can
            // check the specific sender's balance matches the delta
            // and the contract balance increased by amount.
            // However, the difference is about global consistency:
            // The contract's balance is stored externally; the sum of Acc balances
            // must equal address(c).balance.
            // Since there is only one account that can be modified in a single Put,
            // we can assert that:
            // acc.balance (after Put) = acc.balance (before Put) + amount
            // BUT the bug violates through overflow wrapping.

            // Instead we directly check the global invariant using the getter:
            // c.Acc(sender) gives the new balance. The contract balance after Put
            // is balanceBefore + amount (because the call succeeded and value was transferred).
            // So we assert that c.Acc(sender).balance == balanceBefore + amount
            // Only holds for the correct contract because overflow would make it less.
            (uint256 _unlockTime, uint256 senderBalance) = c.Acc(sender);
            assertTrue(senderBalance == balanceBefore + amount);
        }
        // If the call reverted, we don't assert anything (the invariant is preserved).
    }
}

