        vm.assume(unlockTime <= type(uint64).max);
        address user = address(0x1234);
        vm.deal(user, amount);
        vm.prank(user);
        c.Put{value: amount}(unlockTime);
        uint256 storedUnlock = c.Acc(user).unlockTime;
        // The reference contract ensures storedUnlock >= max(block.timestamp, unlockTime).
        // A simplified but general rule: if unlockTime is in the future, the stored value equals unlockTime;
        // if unlockTime is in the past, the stored value is never less than block.timestamp.
        // In contrast, the buggy version simply stores unlockTime, which can be < block.timestamp.
        // The following captures this: if unlockTime <= block.timestamp, the stored unlock time
        // must not be less than block.timestamp.
        if (unlockTime <= block.timestamp) {
            assertTrue(storedUnlock >= block.timestamp);
        } else {
            assertTrue(storedUnlock == unlockTime);
        }
    }
}

