pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 putAmount, uint256 collectAmount) public {
        // Admissible domain: putAmount > 0 to trigger state change, collectAmount <= putAmount to not underflow
        vm.assume(putAmount > 0);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);
        // _unlockTime can be any value here; fuzzer will find one that exposes the bug

        // Deploy a reverter contract that fails on receiving ETH
        Reverter reverter = new Reverter();
        address collector = address(reverter);
        vm.deal(address(this), putAmount);
        vm.deal(collector, 0);

        // Prank as sender to Put with the fuzzed params
        vm.prank(address(this));
        c.Put{value: putAmount}(_unlockTime);

        // Warp past block.timestamp to ensure collect condition may be met
        vm.warp(block.timestamp + 1 days);

        // Record balance before collect attempt
        uint256 balanceBefore = c.Acc(collector).balance;
        // Also record unlockTime set by Put
        uint256 unlockTime = c.Acc(collector).unlockTime;

        // Attempt Collect from the reverter; it should fail
        vm.prank(collector);
        try c.Collect(collectAmount) {
            // If it succeeds, that's unexpected because collector is a Reverter
            revert("Collect succeeded unexpectedly");
        } catch {
            // Expected failure
        }

        // Rule: After a failing Collect, the balance must remain unchanged (reference property)
        // The buggy version sets unlockTime to _unlockTime (< block.timestamp), enabling Collect to succeed
        // when it shouldn't, thus balance changes. We assert balance stayed the same.
        assertEq(c.Acc(collector).balance, balanceBefore);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

