contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialBalance, uint256 addAmount, uint256 unlockTime) public {
        // Restrict to admissible domain: initialBalance must be set so that adding addAmount overflows.
        // We want the require to fail. That means initialBalance + addAmount < initialBalance (overflow).
        vm.assume(addAmount > 0);
        vm.assume(initialBalance <= type(uint256).max - addAmount + 1); // This ensures overflow will happen
        // But we also need initialBalance to be settable. We use a helper to set the state.
        // We deploy a helper contract that will have its Acc modified by first calling Put with initialBalance,
        // then calling Put again with addAmount that causes overflow.
        // The test actor will be a new address.
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(initialBalance, addAmount, unlockTime)))));
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));

        // First call: set Acc[actor].balance to initialBalance
        vm.deal(actor, initialBalance);
        vm.prank(actor);
        c.Put{value: initialBalance}(unlockTime);

        // Now record History length before the second Put that should revert
        uint256 lenBefore = c.LogFile().History.length;

        // Second call: attempt to add addAmount that will cause overflow in acc.balance + msg.value
        vm.deal(actor, addAmount);
        vm.prank(actor);
        try c.Put{value: addAmount}(unlockTime) {
            // If it doesn't revert, our assumption was wrong, but that's okay; we just check the invariant.
        } catch {
            // If it reverts, History length must not increase.
        }

        // The invariant: If the second Put reverted (due to overflow), History length must be unchanged.
        // But if it succeeded, the length may increase. We check: if reverted, lenAfter == lenBefore.
        // However, we can express this as: It is NOT the case that (reverted AND lenAfter > lenBefore).
        // Simpler: assertTrue(!(reverted && lenAfter > lenBefore))
        uint256 lenAfter = c.LogFile().History.length;
        bool reverted = (lenAfter == lenBefore); // This is not perfectly accurate. We need to detect revert.
        // Unfortunately, we don't have the revert flag. We'll use a different approach: we know the require condition.
        // The require will fail if initialBalance + addAmount < initialBalance (mod 2^256).
        // We can compute that: if initialBalance > type(uint256).max - addAmount, then overflow occurs, require fails.
        // In that case, the call MUST revert, and History length MUST NOT increase.
        bool overflowWillHappen = (initialBalance > type(uint256).max - addAmount);
        if (overflowWillHappen) {
            assertTrue(lenAfter == lenBefore);
        } else {
            // If no overflow, it succeeds, length may increase, nothing to assert.
        }
    }
}

